/**
 * Checks if a user has admin privileges by querying the user_roles table
 * @param userId The ID of the user to check
 * @returns A boolean indicating whether the user has admin privileges
 */
export const isAdminUser = async (userId: string): Promise<boolean> => {
  try {
    // Check if the user exists in the user_roles table with role 'admin'
    const { data, error } = await supabase.rpc('has_role', {
      _user_id: userId,
      _role: 'admin'
    });

    if (error) {
      console.error("Error checking admin status:", error);
      return false;
    }

    // If the RPC function isn't available yet, use a fallback direct query
    if (error && error.message.includes("function") && error.message.includes("does not exist")) {
      const { data: roleData, error: roleError } = await supabase
        .from('user_roles')
        .select('*')
        .eq('user_id', userId)
        .eq('role', 'admin')
        .single();

      if (roleError && roleError.code !== 'PGRST116') {
        console.error("Error checking admin role:", roleError);
        return false;
      }

      return !!roleData;
    }

    return !!data;
  } catch (error) {
    console.error("Error checking admin status:", error);
    return false;
  }
};
